const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

let input = '';
rl.on('line', (line) => {
    input += line.trim();
    if (input) {
        let n = parseInt(input, 10);

        function printRod(d) {
            let output = '';
            if (d >= 5) {
                output += "-O|";
            } else {
                output += "O-|";
            }
            d %= 5;
            for (let i = 0; i < d; i++) {
                output += "O";
            }
            output += "-";
            for (let i = 4 - d; i > 0; i--) {
                output += "O";
            }
            console.log(output);
        }

        if (n === 0) {
            printRod(0);
        } else {
            while (n > 0) {
                let d = n % 10;
                printRod(d);
                n = Math.floor(n / 10);
            }
        }
        rl.close();
    }
});

